CREATE TRIGGER community_new_history_insert BEFORE INSERT ON communities BEGIN
 SELECT RAISE(ABORT,'INITIAL_HISTORY_NOT_EMPTY') WHERE (json_type(NEW.state,'$.loans') IS NOT NULL AND (json_type(NEW.state,'$.loans') IS NOT 'array' OR json_array_length(NEW.state,'$.loans') IS NOT 0)) OR (json_type(NEW.state,'$.reviews') IS NOT NULL AND (json_type(NEW.state,'$.reviews') IS NOT 'array' OR json_array_length(NEW.state,'$.reviews') IS NOT 0));
END;
