CREATE TRIGGER community_loan_integrity BEFORE UPDATE ON communities BEGIN
 SELECT RAISE(ABORT,'HISTORY_SHAPE') WHERE (json_type(NEW.state,'$.loans') IS NOT NULL AND json_type(NEW.state,'$.loans') IS NOT 'array') OR (json_type(NEW.state,'$.reviews') IS NOT NULL AND json_type(NEW.state,'$.reviews') IS NOT 'array');
 SELECT RAISE(ABORT,'OFFER_MODE') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.listings') l WHERE (json_type(l.value,'$.offerMode') IS NOT NULL AND (json_type(l.value,'$.offerMode') IS NOT 'text' OR json_extract(l.value,'$.offerMode') NOT IN ('trade','lend','both'))) OR (json_type(l.value,'$.maxLoanDays') IS NOT NULL AND (json_type(l.value,'$.maxLoanDays') IS NOT 'integer' OR json_extract(l.value,'$.maxLoanDays') NOT BETWEEN 1 AND 14)) OR (json_type(l.value,'$.loanTerms') IS NOT NULL AND (json_type(l.value,'$.loanTerms') IS NOT 'text' OR length(json_extract(l.value,'$.loanTerms'))>500)) OR json_type(l.value,'$.loanHeld') IS NOT NULL);
 SELECT RAISE(ABORT,'VENUE_CALENDAR') WHERE json_extract(NEW.state,'$.venues') IS NOT json_extract(OLD.state,'$.venues') AND (
   json_array_length(NEW.state,'$.venues') IS NOT json_array_length(OLD.state,'$.venues') OR EXISTS (SELECT 1 FROM json_each(OLD.state,'$.venues') o LEFT JOIN json_each(NEW.state,'$.venues') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE n.value IS NULL OR json_remove(o.value,'$.windows') IS NOT json_remove(n.value,'$.windows') OR (json_extract(o.value,'$.windows') IS NOT json_extract(n.value,'$.windows') AND (json_type(n.value,'$.windows') IS NOT 'array' OR json_array_length(n.value,'$.windows') NOT BETWEEN 0 AND 28 OR EXISTS (SELECT 1 FROM json_each(n.value,'$.windows') w WHERE json_type(w.value,'$.start') IS NOT 'integer' OR json_type(w.value,'$.end') IS NOT 'integer' OR json_extract(w.value,'$.start')<unixepoch() OR json_extract(w.value,'$.end')>unixepoch()+30*86400 OR json_extract(w.value,'$.start')%900 IS NOT 0 OR json_extract(w.value,'$.end')%900 IS NOT 0 OR json_extract(w.value,'$.end')<json_extract(w.value,'$.start')+1800)))));
 SELECT RAISE(ABORT,'LOAN_IDENTITY') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') GROUP BY json_extract(value,'$.id') HAVING count(*)>1) OR EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o WHERE NOT EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') n WHERE json_extract(n.value,'$.id')=json_extract(o.value,'$.id')));
 SELECT RAISE(ABORT,'LOAN_SHAPE') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') l WHERE json_type(l.value,'$.id') IS NOT 'text' OR json_type(l.value,'$.state') IS NOT 'text' OR json_extract(l.value,'$.state') NOT IN ('REQUESTED','RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW','CLOSED','RESOLVED','DECLINED','CANCELLED','EXPIRED','STALE','CONFLICTED') OR json_extract(l.value,'$.custody') NOT IN ('owner','borrower','unknown','lost') OR json_type(l.value,'$.custody') IS NOT 'text' OR json_extract(l.value,'$.version') IS NOT 1 OR json_type(l.value,'$.sequence') IS NOT 'integer' OR json_extract(l.value,'$.sequence')<1 OR json_type(l.value,'$.createdAt') IS NOT 'integer' OR json_type(l.value,'$.deadline') IS NOT 'integer' OR json_type(l.value,'$.extensions') IS NOT 'array' OR json_type(l.value,'$.issues') IS NOT 'array' OR json_extract(l.value,'$.borrowerId') IS json_extract(l.value,'$.lenderId') OR json_extract(l.value,'$.item.id') IS NOT json_extract(l.value,'$.listingId') OR json_extract(l.value,'$.item.ownerId') IS NOT json_extract(l.value,'$.lenderId') OR json_extract(l.value,'$.deadline') IS NOT min(json_extract(l.value,'$.createdAt')+86400,json_extract(l.value,'$.pickup.start')-3600) OR json_type(l.value,'$.pickup.start') IS NOT 'integer' OR json_extract(l.value,'$.pickup.start')%900 IS NOT 0 OR json_extract(l.value,'$.pickup.end') IS NOT json_extract(l.value,'$.pickup.start')+1800 OR json_type(l.value,'$.returnSlot.start') IS NOT 'integer' OR json_extract(l.value,'$.returnSlot.start')%900 IS NOT 0 OR json_extract(l.value,'$.returnSlot.end') IS NOT json_extract(l.value,'$.returnSlot.start')+1800 OR json_extract(l.value,'$.returnSlot.start')<json_extract(l.value,'$.pickup.start')+86400 OR json_extract(l.value,'$.returnSlot.end')>json_extract(l.value,'$.pickup.end')+coalesce(json_extract(l.value,'$.item.maxLoanDays'),7)*86400);
 SELECT RAISE(ABORT,'LOAN_TERMS_IMMUTABLE') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE json_remove(o.value,'$.state','$.sequence','$.custody','$.pickupReceipt','$.returnReceipt','$.returnReportedAt','$.extensions','$.issues','$.reason','$.resolution','$.closedAt') IS NOT json_remove(n.value,'$.state','$.sequence','$.custody','$.pickupReceipt','$.returnReceipt','$.returnReportedAt','$.extensions','$.issues','$.reason','$.resolution','$.closedAt') OR (o.value IS NOT n.value AND json_extract(n.value,'$.sequence') IS NOT json_extract(o.value,'$.sequence')+(SELECT count(*) FROM json_each(NEW.state,'$.events') e WHERE json_extract(e.value,'$.loanId')=json_extract(n.value,'$.id'))-(SELECT count(*) FROM json_each(OLD.state,'$.events') e WHERE json_extract(e.value,'$.loanId')=json_extract(o.value,'$.id'))));
 SELECT RAISE(ABORT,'LOAN_CREATE_AUTH') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') n WHERE NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o WHERE json_extract(o.value,'$.id')=json_extract(n.value,'$.id')) AND (NEW.operation IS NOT 'loan.request' OR json_extract(n.value,'$.borrowerId') IS NOT NEW.actor_id OR json_extract(n.value,'$.state') IS NOT 'REQUESTED' OR json_extract(n.value,'$.custody') IS NOT 'owner' OR json_extract(n.value,'$.createdAt') IS NOT unixepoch() OR json_extract(n.value,'$.pickup.start')<unixepoch()+7200 OR json_array_length(n.value,'$.extensions') IS NOT 0 OR json_array_length(n.value,'$.issues') IS NOT 0 OR json_type(n.value,'$.pickupReceipt') IS NOT NULL OR json_type(n.value,'$.returnReceipt') IS NOT NULL OR json_type(n.value,'$.returnReportedAt') IS NOT NULL OR json_type(n.value,'$.closedAt') IS NOT NULL OR NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.listings') i WHERE i.value IS json_extract(n.value,'$.item') AND json_extract(i.value,'$.status')='active' AND json_extract(i.value,'$.offerMode') IN ('lend','both')) OR EXISTS (SELECT 1 FROM json_each(OLD.state,'$.blocks') b WHERE json_extract(b.value,'$.blockerId') IN (json_extract(n.value,'$.lenderId'),json_extract(n.value,'$.borrowerId')) AND json_extract(b.value,'$.blockedId') IN (json_extract(n.value,'$.lenderId'),json_extract(n.value,'$.borrowerId')))));
 SELECT RAISE(ABORT,'LOAN_CONSENT') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') n WHERE (NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o WHERE json_extract(o.value,'$.id')=json_extract(n.value,'$.id')) OR (json_extract(n.value,'$.state')='RESERVED' AND EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o WHERE json_extract(o.value,'$.id')=json_extract(n.value,'$.id') AND json_extract(o.value,'$.state')='REQUESTED'))) AND (
 NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.listings') i WHERE json_extract(i.value,'$.id')=json_extract(n.value,'$.listingId') AND json_extract(i.value,'$.ownerId')=json_extract(n.value,'$.lenderId') AND json_extract(i.value,'$.version')=json_extract(n.value,'$.item.version') AND json_extract(i.value,'$.status')='active' AND json_extract(i.value,'$.offerMode') IN ('lend','both'))
 OR NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.members') m WHERE json_extract(m.value,'$.id')=json_extract(n.value,'$.lenderId') AND json_extract(m.value,'$.status')='active' AND json_extract(m.value,'$.version')=json_extract(n.value,'$.memberVersions[0]') AND json_extract(m.value,'$.preferenceVersion')=json_extract(n.value,'$.preferenceVersions[0]') AND EXISTS (SELECT 1 FROM json_each(m.value,'$.availability') w WHERE json_extract(w.value,'$.start')<=json_extract(n.value,'$.pickup.start') AND json_extract(w.value,'$.end')>=json_extract(n.value,'$.pickup.end')) AND EXISTS (SELECT 1 FROM json_each(m.value,'$.venueIds') v WHERE v.value=json_extract(n.value,'$.pickup.venueId')))
 OR NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.members') m WHERE json_extract(m.value,'$.id')=json_extract(n.value,'$.borrowerId') AND json_extract(m.value,'$.status')='active' AND json_extract(m.value,'$.version')=json_extract(n.value,'$.memberVersions[1]') AND json_extract(m.value,'$.preferenceVersion')=json_extract(n.value,'$.preferenceVersions[1]') AND EXISTS (SELECT 1 FROM json_each(m.value,'$.availability') w WHERE json_extract(w.value,'$.start')<=json_extract(n.value,'$.pickup.start') AND json_extract(w.value,'$.end')>=json_extract(n.value,'$.pickup.end')) AND EXISTS (SELECT 1 FROM json_each(m.value,'$.venueIds') v WHERE v.value=json_extract(n.value,'$.pickup.venueId')))
 OR NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.venues') v JOIN json_each(v.value,'$.windows') w WHERE json_extract(v.value,'$.id')=json_extract(n.value,'$.pickup.venueId') AND json_extract(v.value,'$.active')=1 AND json_extract(w.value,'$.start')<=json_extract(n.value,'$.pickup.start') AND json_extract(w.value,'$.end')>=json_extract(n.value,'$.pickup.end'))
 OR NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.venues') v JOIN json_each(v.value,'$.windows') w WHERE json_extract(v.value,'$.id')=json_extract(n.value,'$.returnSlot.venueId') AND json_extract(v.value,'$.active')=1 AND json_extract(w.value,'$.start')<=json_extract(n.value,'$.returnSlot.start') AND json_extract(w.value,'$.end')>=json_extract(n.value,'$.returnSlot.end'))
 OR EXISTS (SELECT 1 FROM json_each(OLD.state,'$.blocks') b WHERE json_extract(b.value,'$.blockerId') IN (json_extract(n.value,'$.lenderId'),json_extract(n.value,'$.borrowerId')) AND json_extract(b.value,'$.blockedId') IN (json_extract(n.value,'$.lenderId'),json_extract(n.value,'$.borrowerId')))));
 SELECT RAISE(ABORT,'LOAN_CHANGE_AUTH') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE o.value IS NOT n.value AND NOT (
   (NEW.operation LIKE 'loan.%' AND NEW.actor_id IN (json_extract(o.value,'$.lenderId'),json_extract(o.value,'$.borrowerId')))
   OR (NEW.operation IN ('moderation.loan.resolve','moderation.suspend','moderation.listing','moderation.venue') AND EXISTS (SELECT 1 FROM json_each(OLD.state,'$.members') m WHERE json_extract(m.value,'$.id')=NEW.actor_id AND json_extract(m.value,'$.role')='moderator'))
   OR (NEW.operation IN ('listing.save','listing.pause','listing.remove','preferences.save','member.block','member.delete') AND json_extract(n.value,'$.state') IN ('STALE','NEEDS_REVIEW'))
   OR (json_extract(o.value,'$.state')='REQUESTED' AND json_extract(n.value,'$.state')='EXPIRED' AND unixepoch()>=json_extract(o.value,'$.deadline'))
   OR (json_extract(n.value,'$.state')='NEEDS_REVIEW' AND ((json_extract(o.value,'$.state')='RESERVED' AND unixepoch()>=json_extract(o.value,'$.pickup.end')+7200) OR (json_extract(o.value,'$.state') IN ('ON_LOAN','RETURN_REPORTED') AND unixepoch()>=coalesce((SELECT json_extract(value,'$.returnSlot.end') FROM json_each(o.value,'$.extensions') WHERE json_extract(value,'$.status')='accepted' ORDER BY key DESC LIMIT 1),json_extract(o.value,'$.returnSlot.end'))+7200)))));
 SELECT RAISE(ABORT,'LOAN_TRANSITION') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE json_extract(o.value,'$.state') IS NOT json_extract(n.value,'$.state') AND NOT (
   (json_extract(o.value,'$.state')='REQUESTED' AND json_extract(n.value,'$.state') IN ('RESERVED','DECLINED','CONFLICTED') AND NEW.operation='loan.vote' AND NEW.actor_id=json_extract(o.value,'$.lenderId') AND unixepoch()<json_extract(o.value,'$.deadline'))
   OR (json_extract(o.value,'$.state')='REQUESTED' AND json_extract(n.value,'$.state')='CANCELLED' AND NEW.operation='loan.cancel')
   OR (json_extract(o.value,'$.state')='REQUESTED' AND json_extract(n.value,'$.state')='EXPIRED' AND unixepoch()>=json_extract(o.value,'$.deadline'))
   OR (json_extract(o.value,'$.state')='REQUESTED' AND json_extract(n.value,'$.state')='STALE' AND NEW.operation IN ('listing.save','listing.pause','listing.remove','preferences.save','member.block','member.delete','moderation.suspend','moderation.listing','moderation.venue','loan.vote'))
   OR (json_extract(o.value,'$.state')='RESERVED' AND json_extract(n.value,'$.state')='CANCELLED' AND NEW.operation='loan.cancel' AND unixepoch()<json_extract(o.value,'$.pickup.start') AND json_type(o.value,'$.pickupReceipt') IS NULL)
   OR (json_extract(o.value,'$.state')='RESERVED' AND json_extract(n.value,'$.state')='ON_LOAN' AND NEW.operation='loan.pickup' AND NEW.actor_id=json_extract(o.value,'$.borrowerId'))
   OR (json_extract(o.value,'$.state')='ON_LOAN' AND json_extract(n.value,'$.state')='RETURN_REPORTED' AND NEW.operation='loan.return.report' AND NEW.actor_id=json_extract(o.value,'$.borrowerId'))
   OR (json_extract(o.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED') AND json_extract(n.value,'$.state')='RETURNED' AND NEW.operation='loan.return' AND NEW.actor_id=json_extract(o.value,'$.lenderId'))
   OR (json_extract(o.value,'$.state')='RETURNED' AND json_extract(n.value,'$.state')='CLOSED' AND NEW.operation='loan.close' AND NEW.actor_id=json_extract(o.value,'$.lenderId') AND json_type(o.value,'$.pickupReceipt')='object' AND json_type(o.value,'$.returnReceipt')='object' AND json_array_length(o.value,'$.issues')=0)
   OR (json_extract(o.value,'$.state')='NEEDS_REVIEW' AND json_extract(n.value,'$.state')='RESOLVED' AND NEW.operation='moderation.loan.resolve' AND EXISTS (SELECT 1 FROM json_each(OLD.state,'$.members') m WHERE json_extract(m.value,'$.id')=NEW.actor_id AND json_extract(m.value,'$.role')='moderator'))
   OR (json_extract(o.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED') AND json_extract(n.value,'$.state')='NEEDS_REVIEW' AND ((NEW.operation IN ('loan.cancel','loan.problem','member.block','member.delete','moderation.suspend','moderation.listing','moderation.venue')) OR (json_extract(o.value,'$.state')='RESERVED' AND unixepoch()>=json_extract(o.value,'$.pickup.end')+7200) OR (json_extract(o.value,'$.state') IN ('ON_LOAN','RETURN_REPORTED') AND unixepoch()>=coalesce((SELECT json_extract(value,'$.returnSlot.end') FROM json_each(o.value,'$.extensions') WHERE json_extract(value,'$.status')='accepted' ORDER BY key DESC LIMIT 1),json_extract(o.value,'$.returnSlot.end'))+7200)))));
 SELECT RAISE(ABORT,'CROSS_MODE_HOLD') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') a JOIN json_each(NEW.state,'$.loops') t JOIN json_each(t.value,'$.listingIds') i WHERE json_extract(a.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW') AND json_extract(t.value,'$.state') IN ('CONFIRMED','NEEDS_REVIEW') AND i.value=json_extract(a.value,'$.listingId'));
 SELECT RAISE(ABORT,'LOAN_DOUBLE_HOLD') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') WHERE json_extract(value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW') GROUP BY json_extract(value,'$.listingId') HAVING count(*)>1);
 SELECT RAISE(ABORT,'LOAN_BORROWER_CAP') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') WHERE json_extract(value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW') GROUP BY json_extract(value,'$.borrowerId') HAVING count(*)>2);
 SELECT RAISE(ABORT,'TRADE_MODE_REQUIRED') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loops') l JOIN json_each(l.value,'$.listingIds') i JOIN json_each(NEW.state,'$.listings') s ON json_extract(s.value,'$.id')=i.value WHERE json_extract(l.value,'$.state') IN ('CONFIRMED','NEEDS_REVIEW') AND coalesce(json_extract(s.value,'$.offerMode'),'trade')='lend');
 SELECT RAISE(ABORT,'LOAN_ITEM_IMMUTABLE') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') l JOIN json_each(OLD.state,'$.listings') o ON json_extract(o.value,'$.id')=json_extract(l.value,'$.listingId') JOIN json_each(NEW.state,'$.listings') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE json_extract(l.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW') AND o.value IS NOT n.value AND NOT (json_remove(o.value,'$.status','$.version') IS json_remove(n.value,'$.status','$.version') AND NEW.operation IN ('loan.close','moderation.loan.resolve') AND json_extract(n.value,'$.status') IN ('paused','removed') AND json_extract(n.value,'$.version')=json_extract(o.value,'$.version')+1 AND EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') q WHERE json_extract(q.value,'$.id')=json_extract(l.value,'$.id') AND json_extract(q.value,'$.state') IN ('CLOSED','RESOLVED'))));
 SELECT RAISE(ABORT,'LOAN_RELEASE_STATE') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') JOIN json_each(NEW.state,'$.listings') i ON json_extract(i.value,'$.id')=json_extract(n.value,'$.listingId') WHERE json_extract(o.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW') AND json_extract(n.value,'$.state') IN ('CLOSED','RESOLVED') AND (json_extract(n.value,'$.closedAt') IS NOT unixepoch() OR json_extract(n.value,'$.custody') NOT IN ('owner','lost') OR json_extract(i.value,'$.status') IS NOT CASE json_extract(n.value,'$.custody') WHEN 'lost' THEN 'removed' ELSE 'paused' END));
END;
