CREATE TRIGGER community_loan_evidence BEFORE UPDATE ON communities BEGIN
 SELECT RAISE(ABORT,'LOAN_RECEIPT_IMMUTABLE') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE (json_type(o.value,'$.pickupReceipt') IS NOT NULL AND json_extract(o.value,'$.pickupReceipt') IS NOT json_extract(n.value,'$.pickupReceipt')) OR (json_type(o.value,'$.returnReceipt') IS NOT NULL AND json_extract(o.value,'$.returnReceipt') IS NOT json_extract(n.value,'$.returnReceipt')) OR (json_type(o.value,'$.returnReportedAt') IS NOT NULL AND json_extract(o.value,'$.returnReportedAt') IS NOT json_extract(n.value,'$.returnReportedAt')) OR (json_type(o.value,'$.closedAt') IS NOT NULL AND json_extract(o.value,'$.closedAt') IS NOT json_extract(n.value,'$.closedAt')));
 SELECT RAISE(ABORT,'LOAN_RECEIPT_AUTH') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE (json_type(o.value,'$.pickupReceipt') IS NULL AND json_type(n.value,'$.pickupReceipt') IS NOT NULL AND (NEW.operation IS NOT 'loan.pickup' OR NEW.actor_id IS NOT json_extract(o.value,'$.borrowerId') OR json_extract(n.value,'$.pickupReceipt.recipientId') IS NOT NEW.actor_id OR json_extract(n.value,'$.pickupReceipt.reportedAt') IS NOT unixepoch() OR json_extract(n.value,'$.custody') IS NOT 'borrower' OR json_extract(o.value,'$.state') NOT IN ('RESERVED','NEEDS_REVIEW') OR json_type(o.value,'$.returnReceipt') IS NOT NULL OR unixepoch()<json_extract(o.value,'$.pickup.start')-600)) OR (json_type(o.value,'$.returnReceipt') IS NULL AND json_type(n.value,'$.returnReceipt') IS NOT NULL AND (NEW.operation IS NOT 'loan.return' OR NEW.actor_id IS NOT json_extract(o.value,'$.lenderId') OR json_extract(n.value,'$.returnReceipt.recipientId') IS NOT NEW.actor_id OR json_extract(n.value,'$.returnReceipt.reportedAt') IS NOT unixepoch() OR json_extract(n.value,'$.custody') IS NOT 'owner' OR json_extract(o.value,'$.state') NOT IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW') OR (json_type(o.value,'$.pickupReceipt') IS NOT 'object' AND json_extract(o.value,'$.state') IS NOT 'NEEDS_REVIEW') OR unixepoch()<json_extract(o.value,'$.pickup.start')-600)) OR (json_type(o.value,'$.returnReportedAt') IS NULL AND json_type(n.value,'$.returnReportedAt') IS NOT NULL AND (NEW.operation IS NOT 'loan.return.report' OR NEW.actor_id IS NOT json_extract(o.value,'$.borrowerId') OR json_extract(n.value,'$.returnReportedAt') IS NOT unixepoch() OR json_type(o.value,'$.pickupReceipt') IS NOT 'object' OR json_type(o.value,'$.returnReceipt') IS NOT NULL)));
 SELECT RAISE(ABORT,'LOAN_CUSTODY_AUTH') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE json_extract(o.value,'$.custody') IS NOT json_extract(n.value,'$.custody') AND NOT ((NEW.operation='loan.pickup' AND NEW.actor_id=json_extract(o.value,'$.borrowerId') AND json_type(n.value,'$.pickupReceipt')='object' AND json_extract(n.value,'$.custody')='borrower') OR (NEW.operation='loan.return' AND NEW.actor_id=json_extract(o.value,'$.lenderId') AND json_type(n.value,'$.returnReceipt')='object' AND json_extract(n.value,'$.custody')='owner') OR (NEW.operation='moderation.loan.resolve' AND json_extract(n.value,'$.custody') IN ('owner','lost') AND EXISTS (SELECT 1 FROM json_each(OLD.state,'$.members') m WHERE json_extract(m.value,'$.id')=NEW.actor_id AND json_extract(m.value,'$.role')='moderator')) OR (json_extract(o.value,'$.state')='RESERVED' AND json_extract(n.value,'$.state')='NEEDS_REVIEW' AND json_extract(n.value,'$.custody')='unknown' AND unixepoch()>=json_extract(o.value,'$.pickup.end')+7200)));
 SELECT RAISE(ABORT,'LOAN_EXTENSION_IMMUTABLE') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') JOIN json_each(o.value,'$.extensions') e LEFT JOIN json_each(n.value,'$.extensions') f ON e.key=f.key WHERE f.value IS NULL OR json_remove(e.value,'$.status','$.decidedAt') IS NOT json_remove(f.value,'$.status','$.decidedAt') OR (json_extract(e.value,'$.status')!='pending' AND e.value IS NOT f.value) OR (e.value IS NOT f.value AND (NEW.operation IS NOT 'loan.extension.vote' OR NEW.actor_id IS NOT json_extract(o.value,'$.lenderId') OR json_extract(f.value,'$.status') NOT IN ('accepted','declined') OR json_extract(f.value,'$.decidedAt') IS NOT unixepoch() OR json_extract(o.value,'$.state') IS NOT 'ON_LOAN')));
 SELECT RAISE(ABORT,'LOAN_EXTENSION_AUTH') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE json_array_length(n.value,'$.extensions')>json_array_length(o.value,'$.extensions') AND (NEW.operation IS NOT 'loan.extend' OR NEW.actor_id IS NOT json_extract(o.value,'$.borrowerId') OR json_extract(o.value,'$.state') IS NOT 'ON_LOAN' OR json_array_length(n.value,'$.extensions') IS NOT json_array_length(o.value,'$.extensions')+1 OR json_array_length(n.value,'$.extensions')>5 OR EXISTS (SELECT 1 FROM json_each(o.value,'$.extensions') WHERE json_extract(value,'$.status')='pending') OR EXISTS (SELECT 1 FROM json_each(n.value,'$.extensions') e WHERE CAST(e.key AS INTEGER)>=json_array_length(o.value,'$.extensions') AND (json_extract(e.value,'$.status') IS NOT 'pending' OR json_extract(e.value,'$.requestedAt') IS NOT unixepoch() OR json_type(e.value,'$.decidedAt') IS NOT NULL))));
 SELECT RAISE(ABORT,'LOAN_EXTENSION_SLOT') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') l JOIN json_each(l.value,'$.extensions') e WHERE json_type(e.value,'$.id') IS NOT 'text' OR json_type(e.value,'$.returnSlot.start') IS NOT 'integer' OR json_extract(e.value,'$.returnSlot.start')%900 IS NOT 0 OR json_extract(e.value,'$.returnSlot.end') IS NOT json_extract(e.value,'$.returnSlot.start')+1800 OR json_extract(e.value,'$.returnSlot.start')<=json_extract(l.value,'$.returnSlot.start') OR json_extract(e.value,'$.returnSlot.end')>json_extract(l.value,'$.pickup.end')+coalesce(json_extract(l.value,'$.item.maxLoanDays'),7)*86400);
 SELECT RAISE(ABORT,'LOAN_ISSUE_AUTH') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE EXISTS (SELECT 1 FROM json_each(o.value,'$.issues') a LEFT JOIN json_each(n.value,'$.issues') b ON a.key=b.key WHERE a.value IS NOT b.value) OR (json_array_length(n.value,'$.issues') IS NOT json_array_length(o.value,'$.issues') AND (NEW.operation IS NOT 'loan.problem' OR NEW.actor_id NOT IN (json_extract(o.value,'$.lenderId'),json_extract(o.value,'$.borrowerId')) OR json_array_length(n.value,'$.issues') IS NOT json_array_length(o.value,'$.issues')+1 OR json_extract(n.value,'$.state') IS NOT 'NEEDS_REVIEW' OR EXISTS (SELECT 1 FROM json_each(n.value,'$.issues') e WHERE CAST(e.key AS INTEGER)>=json_array_length(o.value,'$.issues') AND (json_extract(e.value,'$.authorId') IS NOT NEW.actor_id OR json_extract(e.value,'$.createdAt') IS NOT unixepoch())))));
 SELECT RAISE(ABORT,'LOAN_SYSTEM_SCOPE') WHERE NEW.actor_id='system' AND (json_extract(NEW.state,'$.reviews') IS NOT json_extract(OLD.state,'$.reviews') OR EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE json_remove(o.value,'$.state','$.sequence','$.custody','$.reason') IS NOT json_remove(n.value,'$.state','$.sequence','$.custody','$.reason')));
END;
