CREATE TRIGGER community_reviews BEFORE UPDATE ON communities BEGIN
 SELECT RAISE(ABORT,'REVIEW_IDENTITY') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.reviews') GROUP BY json_extract(value,'$.id') HAVING count(*)>1) OR EXISTS (SELECT 1 FROM json_each(NEW.state,'$.reviews') GROUP BY json_extract(value,'$.kind'),json_extract(value,'$.referenceId'),json_extract(value,'$.reviewerId'),json_extract(value,'$.role') HAVING count(*)>1) OR EXISTS (SELECT 1 FROM json_each(OLD.state,'$.reviews') o WHERE NOT EXISTS (SELECT 1 FROM json_each(NEW.state,'$.reviews') n WHERE json_extract(n.value,'$.id')=json_extract(o.value,'$.id')));
 SELECT RAISE(ABORT,'REVIEW_SHAPE') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.reviews') r WHERE json_type(r.value,'$.id') IS NOT 'text' OR json_extract(r.value,'$.kind') NOT IN ('trade','loan') OR json_extract(r.value,'$.role') NOT IN ('trader','lender','borrower') OR json_extract(r.value,'$.status') NOT IN ('submitted','disputed','supported','excluded') OR json_type(r.value,'$.createdAt') IS NOT 'integer' OR json_type(r.value,'$.publishAt') IS NOT 'integer' OR json_type(r.value,'$.answers') IS NOT 'object' OR json_type(r.value,'$.decisions') IS NOT 'array' OR json_type(r.value,'$.note') IS NOT 'text' OR length(json_extract(r.value,'$.note'))>500 OR EXISTS (SELECT 1 FROM json_each(r.value,'$.answers') WHERE value NOT IN ('yes','no','unknown')) OR (json_extract(r.value,'$.role') IN ('trader','lender') AND ((SELECT count(*) FROM json_each(r.value,'$.answers')) IS NOT 3 OR json_type(r.value,'$.answers.availability') IS NOT 'text' OR json_type(r.value,'$.answers.condition') IS NOT 'text' OR (json_extract(r.value,'$.role')='trader' AND json_type(r.value,'$.answers.commitment') IS NOT 'text') OR (json_extract(r.value,'$.role')='lender' AND json_type(r.value,'$.answers.terms') IS NOT 'text'))) OR (json_extract(r.value,'$.role')='borrower' AND ((SELECT count(*) FROM json_each(r.value,'$.answers')) IS NOT 4 OR json_type(r.value,'$.answers.returnTiming') IS NOT 'text' OR json_type(r.value,'$.answers.care') IS NOT 'text' OR json_type(r.value,'$.answers.disclosure') IS NOT 'text' OR json_type(r.value,'$.answers.coordination') IS NOT 'text')));
 SELECT RAISE(ABORT,'REVIEW_CREATE_AUTH') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.reviews') r WHERE NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.reviews') o WHERE json_extract(o.value,'$.id')=json_extract(r.value,'$.id')) AND (NEW.operation IS NOT 'review.submit' OR json_extract(r.value,'$.reviewerId') IS NOT NEW.actor_id OR json_extract(r.value,'$.subjectId') IS NEW.actor_id OR json_extract(r.value,'$.status') IS NOT 'submitted' OR json_extract(r.value,'$.createdAt') IS NOT unixepoch() OR json_array_length(r.value,'$.decisions') IS NOT 0 OR json_type(r.value,'$.dispute') IS NOT NULL OR json_extract(r.value,'$.publishAt')<unixepoch() OR json_extract(r.value,'$.publishAt')>unixepoch()+7*86400 OR NOT (
 (json_extract(r.value,'$.kind')='trade' AND json_extract(r.value,'$.role')='trader' AND EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loops') l JOIN json_each(l.value,'$.transfers') t WHERE json_extract(l.value,'$.id')=json_extract(r.value,'$.referenceId') AND json_extract(l.value,'$.state') IN ('COMPLETED','RESOLVED') AND json_extract(t.value,'$.id')=json_extract(r.value,'$.transferId') AND json_extract(t.value,'$.receiverId')=NEW.actor_id AND json_extract(t.value,'$.giverId')=json_extract(r.value,'$.subjectId') AND (json_type(t.value,'$.receipt')='object' OR json_extract(r.value,'$.answers.condition')='unknown')))
 OR (json_extract(r.value,'$.kind')='loan' AND json_type(r.value,'$.transferId') IS NULL AND EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') l WHERE json_extract(l.value,'$.id')=json_extract(r.value,'$.referenceId') AND json_extract(l.value,'$.state') IN ('CLOSED','RESOLVED') AND json_extract(r.value,'$.publishAt') IS json_extract(l.value,'$.closedAt')+7*86400 AND ((json_extract(r.value,'$.role')='lender' AND json_extract(l.value,'$.borrowerId')=NEW.actor_id AND json_extract(l.value,'$.lenderId')=json_extract(r.value,'$.subjectId') AND (json_type(l.value,'$.pickupReceipt')='object' OR json_extract(r.value,'$.answers.condition')='unknown')) OR (json_extract(r.value,'$.role')='borrower' AND json_extract(l.value,'$.lenderId')=NEW.actor_id AND json_extract(l.value,'$.borrowerId')=json_extract(r.value,'$.subjectId') AND ((json_type(l.value,'$.returnReceipt')='object' AND json_type(l.value,'$.pickupReceipt')='object') OR json_extract(r.value,'$.answers.care')='unknown') AND (json_type(l.value,'$.pickupReceipt')='object' OR json_extract(r.value,'$.answers.returnTiming')='unknown'))))))));
 SELECT RAISE(ABORT,'REVIEW_IMMUTABLE') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.reviews') o JOIN json_each(NEW.state,'$.reviews') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE json_remove(o.value,'$.status','$.dispute','$.decisions') IS NOT json_remove(n.value,'$.status','$.dispute','$.decisions') OR EXISTS (SELECT 1 FROM json_each(o.value,'$.decisions') a LEFT JOIN json_each(n.value,'$.decisions') b ON a.key=b.key WHERE a.value IS NOT b.value) OR (json_type(o.value,'$.dispute') IS NOT NULL AND json_extract(o.value,'$.dispute') IS NOT json_extract(n.value,'$.dispute')) OR (o.value IS NOT n.value AND NOT (
 (NEW.operation='review.dispute' AND NEW.actor_id=json_extract(o.value,'$.subjectId') AND json_extract(o.value,'$.status')='submitted' AND json_extract(n.value,'$.status')='disputed' AND json_type(o.value,'$.dispute') IS NULL AND json_type(n.value,'$.dispute')='text' AND json_extract(o.value,'$.decisions') IS json_extract(n.value,'$.decisions'))
 OR (NEW.operation='moderation.review.resolve' AND json_extract(o.value,'$.status')='disputed' AND json_extract(n.value,'$.status') IN ('supported','excluded') AND json_array_length(n.value,'$.decisions')=json_array_length(o.value,'$.decisions')+1 AND EXISTS (SELECT 1 FROM json_each(OLD.state,'$.members') m WHERE json_extract(m.value,'$.id')=NEW.actor_id AND json_extract(m.value,'$.role')='moderator') AND EXISTS (SELECT 1 FROM json_each(n.value,'$.decisions') d WHERE CAST(d.key AS INTEGER)=json_array_length(o.value,'$.decisions') AND json_extract(d.value,'$.moderatorId')=NEW.actor_id AND json_extract(d.value,'$.at')=unixepoch() AND json_extract(d.value,'$.status')=json_extract(n.value,'$.status'))))));
END;
