CREATE TRIGGER community_loan_project AFTER UPDATE ON communities BEGIN
 DELETE FROM loan_item_holds WHERE community_id=NEW.id AND NOT EXISTS (SELECT 1 FROM json_each(NEW.state,'$.loans') l WHERE json_extract(l.value,'$.id')=loan_item_holds.loan_id AND json_extract(l.value,'$.listingId')=loan_item_holds.listing_id AND json_extract(l.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW'));
 INSERT INTO loan_item_holds SELECT NEW.id,json_extract(l.value,'$.listingId'),json_extract(l.value,'$.id'),unixepoch() FROM json_each(NEW.state,'$.loans') l WHERE json_extract(l.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW') AND NOT EXISTS (SELECT 1 FROM loan_item_holds h WHERE h.community_id=NEW.id AND h.listing_id=json_extract(l.value,'$.listingId') AND h.loan_id=json_extract(l.value,'$.id'));
END;
