CREATE TRIGGER loan_hold_insert BEFORE INSERT ON loan_item_holds BEGIN
 SELECT RAISE(ABORT,'LOAN_HOLD_INVALID') WHERE NOT EXISTS (SELECT 1 FROM communities c JOIN json_each(c.state,'$.loans') l WHERE c.id=NEW.community_id AND json_extract(l.value,'$.id')=NEW.loan_id AND json_extract(l.value,'$.listingId')=NEW.listing_id AND json_extract(l.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW')) OR EXISTS (SELECT 1 FROM item_holds WHERE community_id=NEW.community_id AND listing_id=NEW.listing_id);
END;
