CREATE TRIGGER loan_hold_retain BEFORE DELETE ON loan_item_holds BEGIN
 SELECT RAISE(ABORT,'LOAN_HOLD_REQUIRED') WHERE EXISTS (SELECT 1 FROM communities c JOIN json_each(c.state,'$.loans') l WHERE c.id=OLD.community_id AND json_extract(l.value,'$.id')=OLD.loan_id AND json_extract(l.value,'$.listingId')=OLD.listing_id AND json_extract(l.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW'));
END;
