CREATE TRIGGER trade_hold_cross_mode BEFORE INSERT ON item_holds BEGIN SELECT RAISE(ABORT,'CROSS_MODE_HOLD') WHERE EXISTS (SELECT 1 FROM loan_item_holds WHERE community_id=NEW.community_id AND listing_id=NEW.listing_id); END;
