CREATE TRIGGER community_extension_schedule BEFORE UPDATE ON communities BEGIN
 SELECT RAISE(ABORT,'LOAN_EXTENSION_SCHEDULE') WHERE EXISTS (
 SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') JOIN json_each(n.value,'$.extensions') e LEFT JOIN json_each(o.value,'$.extensions') prior ON prior.key=e.key
 WHERE (prior.value IS NULL OR (json_extract(prior.value,'$.status')='pending' AND json_extract(e.value,'$.status')='accepted')) AND (
   unixepoch()>=coalesce((SELECT json_extract(value,'$.returnSlot.start') FROM json_each(o.value,'$.extensions') WHERE json_extract(value,'$.status')='accepted' ORDER BY key DESC LIMIT 1),json_extract(o.value,'$.returnSlot.start'))
   OR json_extract(e.value,'$.returnSlot.start')<=coalesce((SELECT json_extract(value,'$.returnSlot.start') FROM json_each(o.value,'$.extensions') WHERE json_extract(value,'$.status')='accepted' ORDER BY key DESC LIMIT 1),json_extract(o.value,'$.returnSlot.start'))
   OR NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.venues') v JOIN json_each(v.value,'$.windows') w WHERE json_extract(v.value,'$.id')=json_extract(e.value,'$.returnSlot.venueId') AND json_extract(v.value,'$.active')=1 AND json_extract(w.value,'$.start')<=json_extract(e.value,'$.returnSlot.start') AND json_extract(w.value,'$.end')>=json_extract(e.value,'$.returnSlot.end'))));
END;
--> statement-breakpoint
CREATE TRIGGER community_appointment_schedule BEFORE UPDATE ON communities BEGIN
 SELECT RAISE(ABORT,'LOAN_APPOINTMENT_CONFLICT') WHERE EXISTS (
 SELECT 1 FROM json_each(NEW.state,'$.loans') a JOIN json_each(NEW.state,'$.loans') b
 WHERE json_extract(a.value,'$.id')<json_extract(b.value,'$.id') AND json_extract(a.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW') AND json_extract(b.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW') AND (json_extract(a.value,'$.lenderId') IN (json_extract(b.value,'$.lenderId'),json_extract(b.value,'$.borrowerId')) OR json_extract(a.value,'$.borrowerId') IN (json_extract(b.value,'$.lenderId'),json_extract(b.value,'$.borrowerId'))) AND EXISTS (
 SELECT 1 FROM (SELECT json_extract(a.value,'$.pickup') AS slot UNION ALL SELECT coalesce((SELECT json_extract(value,'$.returnSlot') FROM json_each(a.value,'$.extensions') WHERE json_extract(value,'$.status')='accepted' ORDER BY key DESC LIMIT 1),json_extract(a.value,'$.returnSlot'))) x JOIN (SELECT json_extract(b.value,'$.pickup') AS slot UNION ALL SELECT coalesce((SELECT json_extract(value,'$.returnSlot') FROM json_each(b.value,'$.extensions') WHERE json_extract(value,'$.status')='accepted' ORDER BY key DESC LIMIT 1),json_extract(b.value,'$.returnSlot'))) y WHERE json_extract(x.slot,'$.start')<json_extract(y.slot,'$.end') AND json_extract(y.slot,'$.start')<json_extract(x.slot,'$.end')));
 SELECT RAISE(ABORT,'TRADE_LOAN_APPOINTMENT_CONFLICT') WHERE EXISTS (
 SELECT 1 FROM json_each(NEW.state,'$.loans') a JOIN json_each(NEW.state,'$.loops') b JOIN json_each(b.value,'$.participants') p
 WHERE json_extract(a.value,'$.state') IN ('RESERVED','ON_LOAN','RETURN_REPORTED','RETURNED','NEEDS_REVIEW') AND json_extract(b.value,'$.state') IN ('CONFIRMED','NEEDS_REVIEW') AND json_extract(p.value,'$.userId') IN (json_extract(a.value,'$.lenderId'),json_extract(a.value,'$.borrowerId')) AND EXISTS (
 SELECT 1 FROM (SELECT json_extract(a.value,'$.pickup') AS slot UNION ALL SELECT coalesce((SELECT json_extract(value,'$.returnSlot') FROM json_each(a.value,'$.extensions') WHERE json_extract(value,'$.status')='accepted' ORDER BY key DESC LIMIT 1),json_extract(a.value,'$.returnSlot'))) x WHERE json_extract(x.slot,'$.start')<json_extract(b.value,'$.end') AND json_extract(b.value,'$.start')<json_extract(x.slot,'$.end')));
END;
