CREATE TRIGGER community_terminal_loans BEFORE UPDATE ON communities BEGIN
 SELECT RAISE(ABORT,'LOAN_CLOSED_IMMUTABLE') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE json_extract(o.value,'$.state') IN ('CLOSED','RESOLVED','DECLINED','CANCELLED','EXPIRED','STALE','CONFLICTED') AND o.value IS NOT n.value);
 SELECT RAISE(ABORT,'LOAN_RESOLUTION_AUTH') WHERE EXISTS (SELECT 1 FROM json_each(OLD.state,'$.loans') o JOIN json_each(NEW.state,'$.loans') n ON json_extract(o.value,'$.id')=json_extract(n.value,'$.id') WHERE json_extract(o.value,'$.resolution') IS NOT json_extract(n.value,'$.resolution') AND (NEW.operation IS NOT 'moderation.loan.resolve' OR json_extract(o.value,'$.state') IS NOT 'NEEDS_REVIEW' OR NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.members') m WHERE json_extract(m.value,'$.id')=NEW.actor_id AND json_extract(m.value,'$.role')='moderator')));
END;
--> statement-breakpoint
CREATE TRIGGER community_trade_review_window BEFORE UPDATE ON communities BEGIN
 SELECT RAISE(ABORT,'TRADE_REVIEW_WINDOW') WHERE EXISTS (SELECT 1 FROM json_each(NEW.state,'$.reviews') r JOIN json_each(OLD.state,'$.loops') l ON json_extract(l.value,'$.id')=json_extract(r.value,'$.referenceId') WHERE json_extract(r.value,'$.kind')='trade' AND NOT EXISTS (SELECT 1 FROM json_each(OLD.state,'$.reviews') o WHERE json_extract(o.value,'$.id')=json_extract(r.value,'$.id')) AND json_extract(r.value,'$.publishAt') IS NOT max(coalesce((SELECT max(json_extract(e.value,'$.at')) FROM json_each(OLD.state,'$.events') e WHERE json_extract(e.value,'$.loopId')=json_extract(l.value,'$.id') AND json_extract(e.value,'$.kind') IN ('receipt','resolved')),0),coalesce((SELECT max(json_extract(t.value,'$.receipt.receivedAt')) FROM json_each(l.value,'$.transfers') t),0))+7*86400);
END;
